window.A2_UNITS = [
{ n:1, title:"COLD BOOT", classes:"1–2", node:"node/01_coldboot", color:"#2fbf9e", theme:"Reconstructing what happened — and what used to happen",
  overview:{
    intro:"Every investigation starts with the log files. This node gives you the two tools you need to read your own past: the simple past for finished events on a timeline, and “used to” for the habits and states that were true for a long stretch of your life and are now closed. One is a single entry in the log; the other is a pattern in the data.",
    goals:["Build affirmative, negative and interrogative sentences in the simple past with regular and irregular verbs.","Use was / were correctly with the right subject, including in questions and short answers.","Describe old habits and old states with used to / didn’t use to, and know when the simple past is the better choice."],
    outcome:"By the end you can give a three-minute account of a year of your life: what happened once, what you used to do every week, and what is no longer true."
  },
  vocab:[
    {term:"to happen", pos:"verb", def:"to take place, to occur — usually without anyone planning it.",
     use:"“Happen” has no passive: never “it was happened”. To ask about an event: “What happened?” with no auxiliary, because “what” is the subject.",
     examples:["What happened at the meeting last night?","Something strange happened when I opened the file."],
     colloc:"what happened · happen to someone · it happened suddenly"},
    {term:"to notice", pos:"verb", def:"to see or realise something, often something small.",
     use:"Followed by a noun, or by a that-clause: “I noticed that the door was open.” Different from “watch” (deliberate) — noticing is accidental.",
     examples:["I noticed a car outside my building.","Nobody noticed that I left early."],
     colloc:"notice a change · barely notice · you may have noticed"},
    {term:"back then", pos:"adverbial phrase", def:"at that time in the past.",
     use:"It works like a time marker for the simple past and for “used to”: “Back then, we used to walk everywhere.” Usually at the start or the end of the sentence.",
     examples:["Back then I didn’t have a phone.","We were poor back then, but we were happy."],
     colloc:"back then · way back then · back in those days"},
    {term:"to move (house)", pos:"verb", def:"to change the place where you live.",
     use:"“Move to” a new place, “move from” the old one, “move out of” a house: “We moved to Bogotá in 2019.”",
     examples:["My family moved to another city when I was ten.","She moved out of her parents’ house last year."],
     colloc:"move to a city · move away · move back home"},
    {term:"childhood", pos:"noun", def:"the period of your life when you were a child.",
     use:"An uncountable-feeling singular noun, normally with a possessive: “my childhood”, “her childhood”. “In my childhood” is correct but “when I was a child” sounds more natural.",
     examples:["I spent my childhood in a small town.","Childhood memories are never complete."],
     colloc:"a happy childhood · childhood friend · since childhood"},
    {term:"to use to (used to)", pos:"semi-modal", def:"a past habit or state that has now stopped.",
     use:"Only exists in the past. Positive: “used to + verb”. Negative and question: “didn’t use to”, “Did you use to…?” — no final -d after “did”.",
     examples:["I used to smoke, but I stopped two years ago.","Did you use to play football at school?"],
     colloc:"used to live · used to be · didn’t use to like"},
    {term:"to quit", pos:"verb", def:"to stop doing something, usually a job or a habit.",
     use:"Irregular and unchanging: quit – quit – quit. Followed by a noun or -ing: “I quit smoking.”",
     examples:["He quit his job in March.","I quit going to the gym after the accident."],
     colloc:"quit a job · quit smoking · quit halfway"},
    {term:"ago", pos:"adverb", def:"before now; counting backwards from today.",
     use:"Always goes AFTER the time period, and always with the simple past — never with the present perfect: “two years ago”, not “ago two years”.",
     examples:["I met her three months ago.","We moved here a long time ago."],
     colloc:"a while ago · long ago · not so long ago"},
    {term:"suddenly", pos:"adverb", def:"very quickly and without warning.",
     use:"Typically at the beginning of a narrative sentence to signal a break in the story: “Suddenly, the lights went out.”",
     examples:["Suddenly everyone stopped talking.","The screen suddenly went black."],
     colloc:"suddenly realise · all of a sudden · quite suddenly"},
    {term:"memory", pos:"noun", def:"something you remember; also your ability to remember.",
     use:"Countable when it is one image from the past (“a memory of my grandfather”), uncountable when it is the mental ability (“a good memory”).",
     examples:["I have a clear memory of that day.","My memory isn’t what it was."],
     colloc:"a vivid memory · from memory · lose your memory"} ],
  grammar:[
    {name:"Simple past: ordinary verbs and the verb “to be”", short:"I worked / I didn’t work / Did you work? — I was, they were.",
     rule:"The simple past reports a finished action or a finished state at a known or implied point in the past. Ordinary verbs use the auxiliary “did” in negatives and questions, and the past form only in the affirmative. The verb “to be” never uses “did”: it changes its own shape into was / were.",
     form:["Affirmative: subject + past form → She worked late. / They went home.","Negative: subject + didn’t + BASE verb → She didn’t work late. (never “didn’t worked”)","Question: Did + subject + BASE verb? → Did she work late?","To be: I / he / she / it WAS · you / we / they WERE → I was tired. They weren’t ready. Were you at home?"],
     notes:["The past form appears in ONE place only. Once “did” is present, the main verb goes back to its base form: “Did you see it?”, not “Did you saw it?”.","Regular verbs add -ed (worked, played). Spelling: consonant + y → -ied (study → studied); one-syllable CVC → double the consonant (stop → stopped).","Irregular verbs must be memorised in threes: go–went–gone, see–saw–seen, take–took–taken, buy–bought–bought.","“Was/were” carries the negative and the question by itself: “I wasn’t there”, “Were they late?” — adding “did” is always wrong.","Short answers repeat the auxiliary, not the verb: “Did you call?” — “Yes, I did.” / “Were you home?” — “No, I wasn’t.”"],
     deep:"Think of the simple past as a photograph rather than a video: it shows the event as one complete block, with a beginning and an end already inside it. That is why it lives so comfortably with closed time markers — yesterday, last week, in 2019, two years ago, when I was twelve. If the time is still open (this week, today, ever in my life) English prefers the present perfect instead, which is exactly the contrast you will meet at node 04. A second thing worth noticing: “to be” behaves differently because it is not an action, it is a link. Actions need a helper (“did”) to form questions; links can invert themselves (“Were you…?”). Learners who mix the two systems produce the classic error “Did you were at home?” — two auxiliaries competing for the same job. Choose one system per sentence: “did + base verb” for actions, “was/were” alone for states.",
     chart:{title:"The two past systems side by side", cols:["","Ordinary verb (work)","Verb to be"], rows:[["Affirmative","I worked late.","I was late."],["Negative","I didn’t work late.","I wasn’t late."],["Yes/no question","Did you work late?","Were you late?"],["Wh- question","Where did you work?","Where were you?"],["Short answer","Yes, I did.","Yes, I was."]]},
     examples:["I called you twice last night, but you didn’t answer.","Where did you go after the class?","She was in the office until nine and then she went home.","We weren’t ready, so the meeting started late."],
     watch:"Never put a past form after “did” or “didn’t”, and never put “did” next to “was/were”. One past marker per clause is the whole rule."},
    {name:"Past habits and states with “used to”", short:"I used to live here. Did you use to work nights?",
     rule:"“Used to + base verb” describes something that was repeatedly true or permanently true in the past and is not true now. It always carries the idea of a contrast with the present. In negatives and questions it becomes “didn’t use to” and “Did … use to?”, with no final -d.",
     form:["Affirmative: subject + used to + base verb → I used to work in a call centre.","Negative: subject + didn’t use to + base verb → I didn’t use to like coffee.","Question: Did + subject + use to + base verb? → Did you use to live in Cali?","Alternative negative (more formal): I never used to eat breakfast."],
     notes:["“Used to” exists only in the past. For present habits use the present simple with an adverb of frequency: “I usually get up at six.”","It works for repeated actions (“I used to run every morning”) and for long states (“He used to be very shy”) — but never for a single event: “I used to break my leg” is wrong.","With a specific number of times or a fixed duration, use the simple past instead: “I went to Cartagena three times”, not “I used to go three times”.","Do not confuse it with “to be used to + -ing” (= to be accustomed to something), which is a different structure about familiarity, not about the past.","“Would” can also describe past habits in storytelling (“Every summer we would drive to the coast”), but it cannot describe past states: “He would be shy” does not mean he was shy."],
     deep:"“Used to” is a comparison machine disguised as a tense. Every time you use it, your listener automatically hears the second half of the sentence even if you do not say it: “I used to smoke” means “…and I don’t now.” This is why it is so useful for talking about change — your city, your job, your body, your opinions. The pronunciation matters more than the spelling: in natural speech “used to” collapses into /ˈjuːstə/, one word, and the two t-sounds merge. That is also the reason the -d disappears after “did”: the sound was never really there. When you compare it with the simple past, remember the difference is not about truth but about framing. “I lived in Medellín for six years” and “I used to live in Medellín” report the same fact; the first frames it as one closed block of time, the second frames it as a former state that has been replaced by a new one.",
     chart:{title:"Choosing between “used to” and the simple past", cols:["Situation","Correct choice","Example"], rows:[["Repeated past habit, now stopped","used to","I used to walk to school."],["Long past state, now different","used to","She used to be a nurse."],["One finished event","simple past","I broke my arm in 2018."],["Counted number of times","simple past","We met twice last month."],["Present habit","present simple + usually","I usually work from home."]]},
     examples:["I used to hate vegetables when I was a kid.","Did you use to have long hair?","He didn’t use to talk much, but now he never stops.","There used to be a cinema on this corner."],
     watch:"After “did”, write “use to” without the -d: “Did you use to smoke?” — and never combine it with a counted number of events."} ],
  speaking:[
    {kind:"Pair work", text:"Reconstruct last Saturday with your partner, hour by hour, using only the simple past. Then repeat the exercise for “a normal Saturday ten years ago” using “used to”."},
    {kind:"Interrogation", text:"One student is the investigator, one is the witness. The investigator asks eight past questions (four with “did”, four with “was/were”). The witness may lie once; the class guesses which answer was false."},
    {kind:"Monologue", text:"Talk for ninety seconds about three things that used to be true about you and are not true now. End each one with “but now…”."} ],
  tips:[
    "If you hear yourself say “did” plus a past verb, stop and restart — one past marker per clause.",
    "Learn irregular verbs in sound families: think–thought / bring–brought / buy–bought.",
    "“Ago” only ever goes with the simple past: two years ago, not “I have gone two years ago”."],
  quiz:{q:"___ you use to work at night when you lived in Bogotá?", options:["Did","Were","Do"], answer:0, explain:"“Use to” takes the auxiliary “did”, and after “did” we write “use to” without the -d."} },

{ n:2, title:"INVENTORY", classes:"5–6", node:"node/02_inventory", color:"#d9a13b", theme:"Counting what you have, and asking without pointing",
  overview:{
    intro:"Two very different skills share this node. First, quantity: English splits nouns into things you can count and things you can only measure, and each group takes a different set of quantifiers. Second, politeness: an indirect question hides the question inside a longer, softer sentence — the difference between demanding information and requesting it.",
    goals:["Classify nouns as count or noncount and choose the right quantifier for each.","Ask how much / how many questions accurately.","Convert direct wh-questions into indirect questions with the correct word order."],
    outcome:"By the end you can describe the contents of a kitchen, a budget or a hard drive with precise quantities, and ask a stranger five polite indirect questions."
  },
  vocab:[
    {term:"amount", pos:"noun", def:"how much there is of something you cannot count.",
     use:"“Amount of + noncount noun”: an amount of money, of time, of data. For countable things use “number of”: “a number of files”.",
     examples:["A huge amount of information was lost.","We spent a small amount of money on it."],
     colloc:"a large amount of · the total amount · a fair amount of"},
    {term:"a few / a little", pos:"quantifiers", def:"a small quantity — “a few” for countable, “a little” for noncount.",
     use:"With “a” they are positive (enough). Without “a” they turn negative: “few friends” means almost none; “little time” means not enough.",
     examples:["I have a few questions and a little time.","Few people know the truth."],
     colloc:"a few minutes · a little help · quite a few"},
    {term:"plenty", pos:"pronoun / quantifier", def:"more than enough.",
     use:"Always with “of” before a noun, and it works for both count and noncount: “plenty of chairs”, “plenty of water”.",
     examples:["Don’t rush — there’s plenty of time.","We have plenty of options."],
     colloc:"plenty of time · plenty of room · plenty more"},
    {term:"container", pos:"noun", def:"the box, bottle or bag that holds something.",
     use:"Containers let you count uncountable things: a bottle of water, a bag of rice, a piece of advice.",
     examples:["Buy two bottles of milk and a bag of sugar.","I need a container for the leftovers."],
     colloc:"a plastic container · a piece of · a slice of"},
    {term:"to wonder", pos:"verb", def:"to want to know something; to ask yourself a question.",
     use:"The classic opening for indirect questions: “I wonder where he lives.” Never invert after it.",
     examples:["I wonder why she left so early.","I was wondering if you could help me."],
     colloc:"I wonder if · I was wondering whether · make you wonder"},
    {term:"whether", pos:"conjunction", def:"the more formal alternative to “if” inside a reported question.",
     use:"Use it when there are two options: “I don’t know whether to stay or go.” After a preposition, only “whether” is possible.",
     examples:["Could you tell me whether the shop is open?","I’m not sure whether he got my message."],
     colloc:"whether or not · whether to · it depends on whether"},
    {term:"quantity", pos:"noun", def:"how much or how many of something there is.",
     use:"More technical than “amount”. Common in shops and reports: “in large quantities”.",
     examples:["We buy rice in large quantities.","The quantity is fine; the quality isn’t."],
     colloc:"a small quantity · in quantity · quantity and quality"},
    {term:"enough", pos:"quantifier / adverb", def:"as much as you need.",
     use:"Before a noun (“enough money”) but AFTER an adjective or adverb (“fast enough”, “good enough”).",
     examples:["We don’t have enough chairs for everyone.","She isn’t old enough to drive."],
     colloc:"enough time · not good enough · more than enough"},
    {term:"to run out of", pos:"phrasal verb", def:"to finish your supply of something.",
     use:"Always with “of” before the noun. The thing that finishes is the object: “We ran out of milk.”",
     examples:["We’ve run out of coffee again.","I ran out of time before the last question."],
     colloc:"run out of money · run out of ideas · nearly run out"},
    {term:"polite", pos:"adjective", def:"showing good manners and respect.",
     use:"“It is polite to + infinitive”: “It’s polite to ask first.” The noun is “politeness”, the opposite is “rude”.",
     examples:["It’s more polite to ask an indirect question.","He was very polite about my mistake."],
     colloc:"polite request · perfectly polite · polite way of asking"} ],
  grammar:[
    {name:"Expressions of quantity with count and noncount nouns", short:"many files, much data, a few minutes, a little help.",
     rule:"Countable nouns have a singular and a plural and answer “how many?”. Noncount nouns have no plural and answer “how much?”. The quantifier you choose must match the type of noun — and some quantifiers work with both.",
     form:["Count only: many, a few, few, several, a number of, how many → many friends, a few ideas.","Noncount only: much, a little, little, a great deal of, an amount of, how much → much time, a little sugar.","Both: some, any, a lot of / lots of, plenty of, enough, no, all → a lot of people, a lot of money.","Make a noncount noun countable with a container or unit: two glasses of water, three pieces of advice."],
     notes:["Noncount nouns take a singular verb: “The news is bad”, “Information is expensive”.","“Much” is rare in positive statements in modern spoken English; use “a lot of” instead: not “I have much work” but “I have a lot of work”.","“Some” in questions signals an offer or a request (“Would you like some coffee?”); “any” is for open questions and negatives (“Is there any coffee?”, “We don’t have any”).","Watch the frequent noncount traps: advice, information, furniture, luggage, homework, money, bread, work, traffic, research.","“A few / a little” are positive; “few / little” alone are negative and quite formal: “Few students passed” = a disappointing number."],
     deep:"The count/noncount split is not really about physics — it is about how English decides to package a thing. Rice is made of countable grains, but English packages it as a mass; furniture is made of individual chairs, but English packages it as a mass too. That is why translation fails you here and lists have to be learnt. A useful test: put the word after “a” and after a number. If “an information” and “three informations” both sound impossible, the noun is noncount, and you need a unit word to count it — a piece of information, an item of furniture, a bit of advice. The second layer is register. “Much” and “many” survive comfortably in negatives and questions (“Do you have many friends?”, “There isn’t much time”), but in affirmative sentences they sound bookish, so speakers reach for “a lot of” and “plenty of”. Getting this right does more for how natural you sound than any single verb tense.",
     chart:{title:"Quantifier map", cols:["Quantifier","Count","Noncount","Example"], rows:[["many / how many","✔","—","How many messages did you get?"],["much / how much","—","✔","How much data do you use?"],["a few / few","✔","—","a few colleagues"],["a little / little","—","✔","a little patience"],["a lot of / plenty of / enough","✔","✔","a lot of files, a lot of time"],["some / any / no","✔","✔","some ideas, some water"]]},
     examples:["How much time do we have, and how many people are coming?","There isn’t much information about the company online.","I only need a little help and a few extra minutes.","We have plenty of chairs but not enough tables."],
     watch:"“Advice”, “information”, “furniture” and “homework” have no plural: say “some advice” or “two pieces of advice”, never “advices”."},
    {name:"Indirect questions from wh-questions (to be, do/does, can)", short:"Where is it? → Could you tell me where it is?",
     rule:"An indirect question wraps the real question inside an introductory phrase. Inside the wrapper, the word order goes back to normal statement order: the subject comes before the verb, and the auxiliaries “do / does / did” disappear completely.",
     form:["Introducer + wh-word + subject + verb: Could you tell me where the station is?","With to be: Where is he? → Do you know where he is?","With do/does: Where does she work? → Can you tell me where she works?","With can: What can I do? → I’d like to know what I can do.","Yes/no questions use if or whether: Is it open? → Do you know if it’s open?"],
     notes:["Never invert twice: “Do you know where is the station?” is the most common error at this level — the inner clause is a statement, not a question.","When “do/does/did” disappears, the tense and the third-person -s move onto the main verb: “Where does he live?” → “…where he lives.”","If the whole sentence starts with a question (Could you tell me…?, Do you know…?) it takes a question mark; if it starts with a statement (I wonder…, I’d like to know…) it takes a full stop.","Common introducers: Could you tell me…, Do you know…, I wonder…, I’d like to know…, Do you have any idea…, Can you remember….","Indirect questions sound noticeably more polite, which is why they are the default with strangers, officials and customer service."],
     deep:"Two grammars are colliding in these sentences, and only one of them can win. A direct question uses inversion — the verb jumps in front of the subject — because inversion is English’s way of marking “this is a question”. But in an indirect question the marking job has already been done by the introducer (“Could you tell me…”), so the inner clause no longer needs it and reverts to plain statement order. Think of it as a nested box: the outer box is the question, the inner box is a piece of information. Once you can see the inner clause as a noun-like chunk — “where he lives” is really just the name of a piece of information — the word order becomes obvious, because you would never invert inside a noun phrase. The politeness effect is worth naming too: by turning a demand into a report of your own curiosity, you give the other person room to decline, and English speakers read that space as courtesy.",
     chart:{title:"Direct → indirect transformation", cols:["Direct question","Change","Indirect version"], rows:[["Where is the exit?","invert back","Could you tell me where the exit is?"],["What time does it open?","drop “does”, add -s","Do you know what time it opens?"],["Did he call you?","drop “did”, past on verb","I wonder if he called you."],["Can I pay by card?","normal order","Could you tell me if I can pay by card?"],["Who is that man?","invert back","Do you have any idea who that man is?"]]},
     examples:["Could you tell me where the meeting room is?","Do you know what time the office closes?","I wonder if she got my email.","I’d like to know how much the repair costs."],
     watch:"After the introducer, write a statement: “…where the station is”, never “…where is the station”."} ],
  speaking:[
    {kind:"Stocktake", text:"In pairs, list what is in your fridge, your bag and your phone storage. Use at least six different quantifiers, and one container expression for each noncount noun."},
    {kind:"Role-play", text:"One student works at an information desk; the other needs six pieces of information. Every question must be indirect. Any direct question loses a point."},
    {kind:"Chain game", text:"The first student asks a direct question; the next converts it into an indirect one and adds a new direct question for the following student."} ],
  tips:[
    "Test a noun with “a” and a number — if both fail, it is noncount and needs a unit word.",
    "Prefer “a lot of” in positive sentences and save “much/many” for questions and negatives.",
    "In indirect questions, delete “do/does/did” and move the tense onto the main verb."],
  quiz:{q:"Could you tell me where ___ ?", options:["the bus stop is","is the bus stop","does the bus stop is"], answer:0, explain:"Inside an indirect question the clause returns to statement order: subject (“the bus stop”) before the verb (“is”)."} },

{ n:3, title:"MIRROR", classes:"10–11", node:"node/03_mirror", color:"#d94f45", theme:"Judging what things are like, and wishing they were different",
  overview:{
    intro:"This node is about evaluation. First you learn the machinery for saying that something is not good enough, too much, or as good as something else — with adjectives and with nouns. Then you learn the grammar of dissatisfaction: “wish”, the structure English uses to talk about the gap between reality and what you would prefer.",
    goals:["Evaluate with too / enough / not … enough and compare with as … as.","Compare using nouns as well as adjectives (too much noise, not enough space).","Express present wishes with wish + past, and past regrets with wish + past perfect."],
    outcome:"By the end you can review a flat, a job or a city in detail and say three things you wish were different."
  },
  vocab:[
    {term:"to complain", pos:"verb", def:"to say that you are not satisfied with something.",
     use:"“Complain about + thing” or “complain to + person”: “I complained to the manager about the noise.”",
     examples:["Everyone complains about the traffic here.","She complained that the room was too small."],
     colloc:"complain about · a written complaint · nothing to complain about"},
    {term:"crowded", pos:"adjective", def:"full of too many people.",
     use:"For places, not people: “a crowded bus”. The noun form is “crowd”; “crowds of people” is very common.",
     examples:["The centre is too crowded on Saturdays.","It was so crowded that we left."],
     colloc:"a crowded street · overcrowded · get crowded"},
    {term:"convenient", pos:"adjective", def:"easy and practical to use or reach.",
     use:"For things and arrangements, not people: “a convenient location”. For people use “available”. Noun: convenience.",
     examples:["The flat is convenient for the university.","Would Friday be convenient for you?"],
     colloc:"convenient location · at your convenience · not very convenient"},
    {term:"expense", pos:"noun", def:"money that you have to spend on something.",
     use:"Countable when it is a specific cost (“travel expenses”), uncountable-feeling in “at great expense”. The adjective is “expensive”.",
     examples:["Rent is my biggest expense.","We cut our expenses by half."],
     colloc:"living expenses · a big expense · at your own expense"},
    {term:"to wish", pos:"verb", def:"to want something that is not real, or that you cannot have.",
     use:"Followed by a past form for a present regret: “I wish I had more time.” “Wish + to + infinitive” exists but is formal and means “want”.",
     examples:["I wish I lived closer to work.","She wishes she could speak Japanese."],
     colloc:"I wish I could · wish you well · make a wish"},
    {term:"decent", pos:"adjective", def:"good enough; of an acceptable standard.",
     use:"Very common in spoken evaluation: “a decent salary”, “a decent meal”. It means satisfactory, not excellent.",
     examples:["It’s not luxury, but it’s a decent place to live.","He earns a decent wage."],
     colloc:"a decent job · decent enough · perfectly decent"},
    {term:"noise", pos:"noun", def:"unwanted or unpleasant sound.",
     use:"Noncount when general (“too much noise”), countable for one specific sound (“a strange noise”). Adjective: noisy.",
     examples:["There’s too much noise from the street.","I heard a noise in the kitchen."],
     colloc:"background noise · make a noise · noise pollution"},
    {term:"space / room", pos:"nouns", def:"the empty area available for something.",
     use:"Both are noncount in this meaning: “not enough space”, “no room for another chair”. “A room” with the article means a bedroom or office.",
     examples:["There isn’t enough space for a table.","Is there room for one more?"],
     colloc:"enough space · plenty of room · make room for"},
    {term:"drawback", pos:"noun", def:"a disadvantage of something otherwise good.",
     use:"Useful in balanced evaluation: “The main drawback is the price.” Opposite: advantage, benefit.",
     examples:["The only drawback is the distance.","Every option has its drawbacks."],
     colloc:"the main drawback · a serious drawback · drawbacks and benefits"},
    {term:"to put up with", pos:"phrasal verb", def:"to accept something unpleasant without complaining.",
     use:"Three parts, always together, always with an object: “I can’t put up with it any more.”",
     examples:["I can’t put up with the noise any longer.","She puts up with a lot at work."],
     colloc:"put up with it · can’t put up with · have to put up with"} ],
  grammar:[
    {name:"Evaluations and comparisons with adjectives and nouns", short:"too small, not big enough, as expensive as, too much noise.",
     rule:"To evaluate, English measures a thing against a standard. “Too” says you are above the acceptable limit; “enough” and “not enough” say you are at or below it; “as … as” says two things are equal. The structure changes depending on whether the word after it is an adjective or a noun.",
     form:["too + adjective → The flat is too small.","adjective + enough → The flat isn’t big enough.","too much / too many + noun → too much noise, too many people.","enough + noun → There aren’t enough parking spaces.","as + adjective + as → It’s as expensive as my old flat. / not as clean as…","as much / many + noun + as → It doesn’t have as much space as the other one."],
     notes:["“Enough” goes BEFORE a noun but AFTER an adjective or adverb: “enough money”, “big enough”, “quickly enough”.","“Too” always means more than you want. It is never a synonym of “very”: “very big” can be good news; “too big” never is.","“Too much” goes with noncount nouns, “too many” with plurals — the same count/noncount split you met at node 02.","“Too + adjective + to + infinitive” compresses a whole evaluation: “It’s too far to walk.” The negative counterpart is “not … enough to”: “He isn’t old enough to drive.”","In negative comparisons both “not as … as” and “not so … as” are possible; the first is far more common in speech."],
     deep:"Every evaluation has three hidden parts: the thing, the quality and the invisible standard. When you say “the room is too small”, you are not describing a size — you are reporting that the size fails a purpose you have in mind (small for what? for four people, for a desk). This is why native speakers so often finish an evaluation with an infinitive or a “for” phrase: “too small for a family”, “not quiet enough to work in”. Adding that second half makes your English sound analytical rather than merely negative. The adjective/noun distinction is mechanical but unforgiving: “too much expensive” and “too many noise” are both broken because “too much/many” only ever modifies nouns, while bare “too” only ever modifies adjectives and adverbs. Say the sentence in your head and ask what word comes next; that single question fixes almost every error in this structure.",
     chart:{title:"Choosing the right evaluation frame", cols:["Meaning","With adjective","With noun"], rows:[["More than acceptable","too expensive","too much rent / too many bills"],["Sufficient","cheap enough","enough money / enough rooms"],["Insufficient","not big enough","not enough space"],["Equal","as clean as","as much light as"],["Not equal","not as modern as","not as many options as"]]},
     examples:["This place is too far from the centre and it isn’t cheap enough.","There’s too much noise and not enough parking.","My new job isn’t as stressful as the old one.","It doesn’t have as many rooms as we wanted, but it’s convenient."],
     watch:"“Enough” after adjectives, before nouns: “fast enough”, “enough time”. Never “enough fast”."},
    {name:"Wishes", short:"I wish I had more time. I wish I hadn’t said that.",
     rule:"“Wish” talks about the distance between reality and what you want. To go one step away from reality, you move the verb one step back in time: a present wish takes a past form, and a past regret takes the past perfect.",
     form:["Present / general wish: wish + past simple → I wish I lived alone. (I don’t.)","Present wish with “to be”: wish + were (all persons) → I wish I were taller.","Ability or possibility: wish + could → I wish I could drive.","Past regret: wish + past perfect → I wish I had studied more. / I wish I hadn’t sent that email.","Annoyance about someone else: wish + would → I wish you would listen."],
     notes:["The past form after “wish” is not about past time — it signals unreality. “I wish I had a car” is about now.","“Were” is standard after “wish” for every person in careful English (“I wish she were here”), though “was” is common in informal speech.","“I wish I would…” is impossible for your own actions; use “could” or a simple past instead.","“Hope” and “wish” are not interchangeable: “hope” is for possible futures (“I hope you pass”), “wish” is for the impossible or the contrary-to-fact.","In the negative, the wish flips the reality: “I wish I hadn’t told him” means you did tell him and you regret it."],
     deep:"“Wish” is your first encounter with the unreal past, the same machinery that later powers second and third conditionals at nodes 15 and beyond. English marks unreality by backshifting: one step back from the present gives you the past simple and means “not true now”; one step back from the past gives you the past perfect and means “not true then, and I cannot change it”. Notice how much emotional information the choice carries. “I wish I lived in Madrid” is a dream about the present; “I wish I had moved to Madrid” is regret about a decision. Learners often keep the tense in the present (“I wish I have more time”), which quietly destroys the meaning, because a present tense after “wish” claims the thing is real. Finally, “I wish you would…” deserves its own note: it is not really a wish at all but a polite complaint, and English speakers use it to criticise a repeated behaviour without saying “stop it”.",
     chart:{title:"Wish patterns and what they mean", cols:["Pattern","Reality","Meaning"], rows:[["I wish I had a car.","I don’t have one.","present wish"],["I wish I were taller.","I’m not.","unreal present state"],["I wish I could swim.","I can’t.","missing ability"],["I wish I had studied.","I didn’t.","past regret"],["I wish I hadn’t lied.","I did lie.","regret about an action"],["I wish you would call.","You don’t.","complaint / request"]]},
     examples:["I wish I lived closer to the office — the commute is too long.","She wishes she had taken the other job.","I wish I could help you, but I’m busy all week.","I wish you wouldn’t leave the door open."],
     watch:"After “wish”, never use a present tense: “I wish I had time”, not “I wish I have time”."} ],
  speaking:[
    {kind:"Review", text:"Evaluate your neighbourhood in six sentences: two with “too”, two with “enough”, two with “as … as”. Then add one drawback you have to put up with."},
    {kind:"Wish circle", text:"Each student says one present wish and one past regret. The next student must react with a follow-up question before adding their own."},
    {kind:"Negotiation", text:"Two flatmates compare two apartments. One prefers A, the other B. Each must use nouns and adjectives in their comparisons and finish with a compromise."} ],
  tips:[
    "Finish an evaluation with a purpose (“too small for four people”) — it sounds far more natural.",
    "“Too much” + noncount, “too many” + plural, plain “too” + adjective.",
    "Backshift after “wish”: present wish → past form; past regret → past perfect."],
  quiz:{q:"The flat is nice, but it isn’t ___ for three people.", options:["big enough","enough big","too big"], answer:0, explain:"“Enough” follows an adjective: big enough. “Too big” would mean the opposite problem."} },

{ n:4, title:"TIMELINE", classes:"14–15", node:"node/04_timeline", color:"#5b8def", theme:"Closed time versus open time, and putting a story in order",
  overview:{
    intro:"This is the node where most learners either break through or plateau. The simple past and the present perfect describe the same events but frame time differently: one closes the file, the other keeps it open. Once that is clear, you learn the connectors that sequence a narrative so a listener can follow it without a map.",
    goals:["Choose between the simple past and the present perfect according to the time frame.","Use ever, never, already, yet, just, since and for with the present perfect.","Order a story or a process with first, then, after that, next and finally."],
    outcome:"By the end you can tell your work or study history accurately, and explain a five-step process in clear sequence."
  },
  vocab:[
    {term:"experience", pos:"noun", def:"knowledge or skill you get from doing something; also an event you lived through.",
     use:"Noncount for knowledge (“two years of experience”), countable for a single event (“a strange experience”).",
     examples:["I have three years’ experience in customer service.","Moving abroad was an amazing experience."],
     colloc:"work experience · from experience · a bad experience"},
    {term:"so far", pos:"adverbial phrase", def:"up to now, in a period that is still open.",
     use:"A classic present perfect signal: “I’ve read three chapters so far.” Usually at the end of the sentence.",
     examples:["So far we haven’t had any problems.","How many have you finished so far?"],
     colloc:"so far so good · so far this year · nothing so far"},
    {term:"yet", pos:"adverb", def:"used in negatives and questions for something expected but not done.",
     use:"Goes at the end: “Have you finished yet?”, “I haven’t decided yet.” Never in affirmative sentences.",
     examples:["I haven’t sent the report yet.","Has the package arrived yet?"],
     colloc:"not yet · haven’t yet · yet again"},
    {term:"already", pos:"adverb", def:"earlier than expected; before now.",
     use:"Normally between “have” and the past participle: “I’ve already eaten.” In a question it shows surprise: “Have you already finished?”",
     examples:["She has already left the office.","We’ve already seen that film."],
     colloc:"already done · already there · already too late"},
    {term:"to achieve", pos:"verb", def:"to succeed in doing something after effort.",
     use:"Takes a concrete object: achieve a goal, a result, success. Not used for objects you obtain: you achieve a goal, you get a car.",
     examples:["She has achieved a lot in two years.","We achieved everything we planned."],
     colloc:"achieve a goal · a great achievement · achieve success"},
    {term:"step", pos:"noun", def:"one action in a sequence.",
     use:"Instructions are built on it: “step by step”, “the first step”, “the next step is to + verb”.",
     examples:["The first step is to open the file.","We did it step by step."],
     colloc:"the next step · step by step · a big step forward"},
    {term:"finally", pos:"adverb", def:"as the last thing; also after a long wait.",
     use:"Two meanings. Sequencing: “Finally, add the sauce.” Relief: “He finally answered.” Not the same as “at the end”, which is about position.",
     examples:["Finally, press Save.","They finally called me back."],
     colloc:"and finally · finally arrive · finally over"},
    {term:"since / for", pos:"prepositions", def:"“since” marks a starting point; “for” marks a duration.",
     use:"Since 2019, since Monday, since I was a child · for three years, for a long time, for ages.",
     examples:["I’ve worked here since March.","I’ve worked here for four months."],
     colloc:"ever since · for ages · for the last two years"},
    {term:"to look up", pos:"phrasal verb", def:"to search for information.",
     use:"Separable: “look it up”, “look up the word”. The pronoun always goes in the middle.",
     examples:["I looked up the address online.","If you don’t know it, look it up."],
     colloc:"look up a word · look it up · look up the details"},
    {term:"recently", pos:"adverb", def:"a short time ago; in the last few days or weeks.",
     use:"Works with the present perfect (“I’ve recently moved”) and, when the moment is specific, with the simple past (“I saw him recently”).",
     examples:["Have you seen her recently?","I’ve recently started a new course."],
     colloc:"quite recently · until recently · recently published"} ],
  grammar:[
    {name:"Simple past vs present perfect", short:"I saw it yesterday. / I’ve seen it three times.",
     rule:"The simple past places an event inside a finished period of time. The present perfect connects a past event to now: either the period is still open, or the result still matters, or the exact time is irrelevant.",
     form:["Simple past: subject + past form (+ finished time) → I sent it yesterday.","Present perfect: subject + have/has + past participle → I have sent it.","Negative/question: I haven’t sent it. / Have you sent it?","Typical past markers: yesterday, last week, in 2020, two days ago, when I was young.","Typical perfect markers: ever, never, already, yet, just, so far, this week, since, for, recently."],
     notes:["Once you name a finished time, the present perfect becomes impossible: “I have seen him yesterday” is always wrong.","Experience questions start in the perfect and continue in the past: “Have you been to Spain?” — “Yes, I went in 2019.”","“For” + duration and “since” + starting point both need the present perfect when the situation continues: “I’ve lived here for six years.”","News is announced in the present perfect and then developed in the simple past: “The company has hired a new director. She started on Monday.”","In American English the simple past sometimes replaces the perfect with “just” and “already” (“I just ate”); both are accepted, but the perfect is safer in exams."],
     deep:"Try to stop asking “when did it happen?” and start asking “is the box closed?”. The simple past puts the event in a closed box: yesterday, last night, in 2019 — boxes you cannot add anything to. The present perfect puts the event in a box that is still on the table: today, this week, in my life so far — boxes where another event could still be added. That is why “I have written three emails today” makes sense (the day is not over) and “I have written three emails yesterday” does not. The second job of the present perfect is relevance: “I’ve lost my keys” tells you about a present problem, while “I lost my keys” is just a story. Because Spanish maps these tenses differently, the reliable strategy is not translation but signal-hunting: find the time expression in the sentence, decide whether it is open or closed, and let it choose the tense for you.",
     chart:{title:"Which tense does the time expression demand?", cols:["Time expression","Tense","Example"], rows:[["yesterday / last week / in 2020 / ago","simple past","I called her last week."],["when I was a child","simple past","I lived in Cali when I was a child."],["today / this week / this year","present perfect","I’ve had three meetings today."],["ever / never / already / yet / just","present perfect","Have you ever flown business class?"],["since 2019 / for six years","present perfect","She’s worked here since 2019."],["no time mentioned, result matters","present perfect","I’ve broken my phone."]]},
     examples:["I’ve worked in three companies, but I only stayed a year in the first one.","Have you finished the report yet? — Yes, I finished it this morning.","She has just left, so you missed her by two minutes.","We haven’t had any complaints so far this month."],
     watch:"Finished time and the present perfect never share a sentence: “I have visited them last summer” must be “I visited them last summer”."},
    {name:"Sequence adverbs: first, then, after that, next, finally", short:"First… then… after that… finally.",
     rule:"Sequence adverbs are signposts. They do not change the tense of the verb; they tell your listener where they are in the story or the process, and they are punctuated as introductory elements.",
     form:["Opening: First, / First of all, / To begin with,","Middle: Then / Next / After that / Later / Meanwhile","Closing: Finally, / In the end, / Eventually,","With clauses instead of adverbs: After I finished, I called her. / Before leaving, check the door."],
     notes:["“Then” is the only one that comfortably appears without a comma: “Then we ate.” The others usually take one when they open the sentence.","“After that” is a complete adverbial and needs no noun; “after” alone must be followed by a noun or clause: “after that” vs “after the meeting”.","Do not confuse “at the end” (position: at the end of the film) with “in the end” (result: in the end we stayed home) or “finally” (last in a list).","“Eventually” means after a long time or many difficulties — it is not simply the last item in a list.","Use “meanwhile” for two things happening at the same time: “Meanwhile, I was waiting outside.”"],
     deep:"Sequencing is where grammar becomes rhetoric. A speaker who marks their steps is easy to follow even when their vocabulary is limited, and a speaker who does not mark them sounds disorganised even with perfect verb forms. Two habits will make the difference. First, be consistent: if you open with “first”, close with “finally” — a list that begins and never ends leaves your listener waiting. Second, do not put a marker on every single sentence; three or four signposts in a paragraph is persuasive, one on every clause sounds like a recipe read aloud. Combining them with time clauses gives you variety: “First, I checked the log. After I found the error, I called the team. In the end, we restarted the server.” Notice that the sequence words carry the order, so the tenses can stay simple — that is exactly the point of them.",
     chart:{title:"Sequencing toolkit", cols:["Function","Expressions","Note"], rows:[["Start","First, / First of all, / To begin with,","comma after"],["Continue","Then / Next / After that / Later","“then” needs no comma"],["Same time","Meanwhile / At the same time","two parallel actions"],["End of a list","Finally, / Lastly,","closes the sequence"],["Final result","In the end / Eventually","outcome, not position"]]},
     examples:["First, open the app. Then enter your code. After that, choose a plan. Finally, confirm.","We tried three suppliers. In the end, we went back to the first one.","Meanwhile, the rest of the team was still waiting for the file.","After I sent the email, I realised I had forgotten the attachment."],
     watch:"“In the end” = the final result; “at the end” = the final part of something. They are not interchangeable."} ],
  speaking:[
    {kind:"Interview", text:"Ask your partner about their experience: three present-perfect questions (Have you ever…?) followed by simple-past follow-ups (When did you…? Where was it?)."},
    {kind:"Instructions", text:"Explain a five-step process from your own life — cooking, commuting, a work task — using all five sequence adverbs, and no notes."},
    {kind:"Two truths", text:"Say three present-perfect experience statements, one false. The group asks past-tense questions to find the lie."} ],
  tips:[
    "Hunt for the time expression first; it decides the tense for you.",
    "Start with the perfect for experience, then switch to the past for details.",
    "Open with “first” only if you plan to close with “finally”."],
  quiz:{q:"I ___ that film last weekend, and I’ve already seen it twice this year.", options:["watched","have watched","was watching"], answer:0, explain:"“Last weekend” is finished time, so the simple past is required; the second clause has open time (“this year”) and takes the present perfect."} },

{ n:5, title:"FORECAST", classes:"19–20", node:"node/05_forecast", color:"#2fbf9e", theme:"Plans and predictions, needs and advice",
  overview:{
    intro:"Two systems for talking about what is coming and what has to be done. “Be going to” and “will” both point at the future but come from different places — one from evidence and intention, the other from the moment of speaking. Then modals let you grade obligation, from a gentle suggestion to a non-negotiable requirement.",
    goals:["Distinguish be going to (plan, evidence) from will (decision at the moment, prediction, promise).","Express degrees of necessity with have to, need to, must and don’t have to.","Give suggestions and advice with should, ought to, could and had better."],
    outcome:"By the end you can present a plan for the next six months and give a colleague graded advice about a decision."
  },
  vocab:[
    {term:"to plan", pos:"verb", def:"to decide in advance what you are going to do.",
     use:"“Plan to + infinitive” or “plan on + -ing”: “We plan to move in July.” Noun: a plan; “make plans”, not “do plans”.",
     examples:["I’m planning to study abroad next year.","What are your plans for the weekend?"],
     colloc:"make a plan · according to plan · plan ahead"},
    {term:"deadline", pos:"noun", def:"the time by which something must be finished.",
     use:"“Meet a deadline” (succeed) or “miss a deadline” (fail). With “by”: “The deadline is by Friday” → better: “The deadline is Friday.”",
     examples:["We have to meet the deadline on Friday.","The deadline has been moved to next week."],
     colloc:"a tight deadline · meet the deadline · miss a deadline"},
    {term:"to be likely to", pos:"expression", def:"probable; there is a good chance of it.",
     use:"“Be likely to + verb” or “It’s likely that…”: “Prices are likely to rise.” The opposite is “unlikely”.",
     examples:["It’s likely to rain this afternoon.","She’s unlikely to accept the offer."],
     colloc:"highly likely · not likely · likely outcome"},
    {term:"to require", pos:"verb", def:"to need something as a rule or a condition.",
     use:"More formal than “need”, common in rules: “The job requires two years’ experience.” Passive: “Applicants are required to…”.",
     examples:["This position requires an advanced level of English.","You’re required to wear ID at all times."],
     colloc:"a requirement · required by law · require attention"},
    {term:"to warn", pos:"verb", def:"to tell someone about a danger or a problem in advance.",
     use:"“Warn someone about something” or “warn someone (not) to do something”: “She warned me not to trust him.”",
     examples:["I warned you about the traffic.","They warned us to arrive early."],
     colloc:"a warning · warn against · fair warning"},
    {term:"urgent", pos:"adjective", def:"needing immediate attention.",
     use:"For situations and tasks, not people: “an urgent problem”. Adverb: “urgently”. Noun: “urgency”.",
     examples:["This is urgent — we need it today.","She urgently needs an answer."],
     colloc:"urgent matter · nothing urgent · a sense of urgency"},
    {term:"had better", pos:"semi-modal", def:"strong advice with a hint of consequence if you don’t follow it.",
     use:"Always “had better + base verb”, contracted to “’d better”. Negative: “had better not”, never “hadn’t better”.",
     examples:["You’d better call him before he leaves.","We’d better not be late again."],
     colloc:"you’d better · had better not · I’d better go"},
    {term:"in charge of", pos:"expression", def:"responsible for a task or a group.",
     use:"“In charge of + noun / -ing”: “She’s in charge of hiring.” Different from “responsible to”, which is about who your boss is.",
     examples:["Who’s in charge of the schedule?","I’m in charge of training the new staff."],
     colloc:"put someone in charge · in charge of a team · take charge"},
    {term:"to postpone", pos:"verb", def:"to move something to a later time.",
     use:"Followed by a noun or -ing, never an infinitive: “We postponed the meeting”, “postpone making a decision”. Informal equivalent: “put off”.",
     examples:["They postponed the trip until August.","Let’s not postpone this any longer."],
     colloc:"postpone a decision · indefinitely postponed · put off"},
    {term:"backup", pos:"noun / adjective", def:"a copy or an alternative in case the first one fails.",
     use:"“A backup plan”, “make a backup”. As a verb it splits into two words: “back up your files”.",
     examples:["We need a backup plan for Friday.","Did you back up the data?"],
     colloc:"backup plan · daily backup · back up the files"} ],
  grammar:[
    {name:"Future with “be going to” and “will”", short:"I’m going to study tonight. / I’ll help you.",
     rule:"“Be going to” presents the future as already decided or already visible in the present: a plan you made before speaking, or evidence in front of you. “Will” presents the future as decided at this moment: an instant decision, an offer, a promise, or a personal prediction.",
     form:["Going to: subject + am/is/are + going to + base verb → She’s going to look for a new job.","Will: subject + will + base verb → I’ll call you tonight. Negative: won’t.","Questions: Are you going to apply? / Will you be there?","Present continuous for fixed arrangements: I’m meeting the client at four."],
     notes:["Prior intention takes “going to”; the decision existed before you spoke: “I’m going to sell my car.”","Spontaneous reaction takes “will”: the phone rings and you say “I’ll get it.”","Evidence in the present takes “going to”: “Look at those clouds — it’s going to rain.”","Offers, promises and refusals always take “will”: “I’ll help you”, “I promise I won’t forget”, “He won’t listen”.","For a fixed arrangement with a time and a place, the present continuous is often the most natural of the three: “We’re flying on Tuesday.”"],
     deep:"The two forms are not competing translations of one idea; they encode where the future comes from. “Be going to” is grammatically a present tense — literally “I am on my way to doing this” — so it always contains something that exists now: your intention, or evidence you can point at. “Will” contains no present at all, which is why it fits the instant of speaking so well: decisions taken as you speak, offers made as you make them, predictions based on nothing but your own opinion. Two consequences follow. First, in a prediction with visible evidence, “going to” is stronger: “She’s going to fall!” is what you shout when you see her slipping. Second, in the main clause of a first conditional (node 09) English prefers “will”, because that future is generated by a condition rather than by a present plan. When both feel possible, ask yourself: did I decide this before I opened my mouth? If yes, “going to”.",
     chart:{title:"Which future form?", cols:["Situation","Form","Example"], rows:[["Plan made before speaking","be going to","I’m going to take a course."],["Evidence you can see now","be going to","The battery’s going to die."],["Decision at this moment","will","I’ll take the red one."],["Offer, promise, refusal","will","I’ll drive you. / I won’t tell anyone."],["Opinion-based prediction","will","I think prices will fall."],["Fixed arrangement","present continuous","We’re meeting at six."]]},
     examples:["I’m going to start the course in September — I already paid for it.","That box looks heavy. I’ll give you a hand.","Look at the queue. We’re going to be late.","Don’t worry, I won’t say anything to her."],
     watch:"After “will” and after “going to”, the verb stays in the base form: “I will call”, “I’m going to call” — never “to call” or “calling”."},
    {name:"Modals for necessity and suggestion", short:"You have to register. You should rest. You’d better hurry.",
     rule:"Modals grade how strong an idea is. For necessity English runs from “must / have to” (no choice) through “need to” (practical necessity) to “don’t have to” (free choice). For advice it runs from “could” (an option) through “should / ought to” (recommendation) to “had better” (urgent, with a consequence).",
     form:["Necessity: must / have to / need to + base verb → You have to show your ID.","No necessity: don’t have to / don’t need to → You don’t have to pay in advance.","Prohibition: mustn’t / can’t → You mustn’t use your phone here.","Advice: should / shouldn’t / ought to / had better (not) → You should get some sleep.","Weak suggestion: could / might want to → You could ask your manager first."],
     notes:["“Mustn’t” and “don’t have to” are opposites, not synonyms: “You mustn’t tell her” = it is forbidden; “You don’t have to tell her” = it is optional. This is the single most valuable distinction in this node.","“Have to” speaks about external rules (the law, your boss, the schedule); “must” often sounds like the speaker’s own authority and is more common in written notices than in conversation.","Modals have no -s, no “to” and no “do”: “She should call”, “Should I call?”, never “She shoulds” or “Does she should”.","“Have to” is the only one that conjugates and has all tenses: had to, will have to, has to.","“Had better” is stronger than “should” and implies a bad outcome if the advice is ignored: “You’d better leave now or you’ll miss it.”"],
     deep:"Think of these modals as a volume dial rather than a list of words. On the necessity dial, “must” and “have to” are at maximum, “need to” slightly below, “should” is a recommendation, “could” is barely a suggestion, and “don’t have to” switches the dial off entirely. Speakers move along the dial for social reasons, not grammatical ones: telling your boss “you must send this” is a serious face-threat, while “you might want to send this” says the same thing without cost. The negative side is where meanings flip rather than fade, so it repays memorising as pairs: must → mustn’t (forbidden), have to → don’t have to (optional), should → shouldn’t (bad idea), had better → had better not (warning). One last structural note: because true modals never change form, all the tense work is done by “have to” — “I had to work yesterday”, “I’ll have to work tomorrow” — which is why it survives in real speech far more than “must”.",
     chart:{title:"The necessity and advice dial", cols:["Strength","Positive","Negative","Meaning of the negative"], rows:[["Maximum","must / have to","mustn’t","forbidden"],["Strong practical","need to","don’t need to","not necessary"],["Neutral rule","have to","don’t have to","optional"],["Advice","should / ought to","shouldn’t","bad idea"],["Urgent advice","had better","had better not","warning"],["Option","could / might want to","—","weak suggestion"]]},
     examples:["You have to bring your ID, but you don’t have to pay anything.","You mustn’t share this password with anyone.","You should talk to her before the meeting — you ought to explain your side.","We’d better book now; the flights are filling up."],
     watch:"“Don’t have to” is freedom; “mustn’t” is prohibition. Mixing them changes your meaning completely."} ],
  speaking:[
    {kind:"Pitch", text:"Present your plan for the next six months in one minute: three sentences with “going to”, two predictions with “will”, one fixed arrangement in the present continuous."},
    {kind:"Advice clinic", text:"One student describes a real problem. Three others respond, each at a different volume: “you could…”, “you should…”, “you’d better…”. The group ranks which was most appropriate."},
    {kind:"Rules poster", text:"In pairs, write the six rules of a place you know using must, mustn’t, have to and don’t have to. Read them out; the class guesses the place."} ],
  tips:[
    "Decided before you spoke? “Going to”. Deciding as you speak? “Will”.",
    "“Don’t have to” ≠ “mustn’t” — check which one you really mean.",
    "Only “have to” can change tense; “must” has no past of its own."],
  quiz:{q:"You ___ wear a suit — the office is completely casual.", options:["don’t have to","mustn’t","shouldn’t have to"], answer:0, explain:"There is no obligation, so “don’t have to”. “Mustn’t” would mean suits are forbidden."} },

{ n:6, title:"HANDSHAKE", classes:"23–24", node:"node/06_handshake", color:"#d9a13b", theme:"Two-part verbs and the art of asking someone to do something",
  overview:{
    intro:"A handshake is a protocol: a request, a response, an agreement. This node gives you the everyday verbs that come in two parts — turn off, pick up, put away — and the polite frames English uses to ask for a favour, including the one that famously inverts your answer: “Would you mind…?”",
    goals:["Use separable and inseparable two-part verbs with the right word order.","Respond to requests with will, sure, of course and I’m afraid I can’t.","Make and answer requests with can, could, would and Would you mind + -ing."],
    outcome:"By the end you can ask for six different favours at three levels of politeness, and respond to requests naturally in either direction."
  },
  vocab:[
    {term:"to turn off / turn on", pos:"phrasal verb", def:"to stop or start a machine, light or tap.",
     use:"Separable: “turn off the light” or “turn the light off”; with a pronoun the middle is obligatory: “turn it off”.",
     examples:["Could you turn off the air conditioning?","Turn it on and see if it works."],
     colloc:"turn off the lights · turn on the news · turn it off"},
    {term:"to pick up", pos:"phrasal verb", def:"to lift something; to collect a person or thing; to answer a call.",
     use:"Separable, with several meanings. Context decides: “pick up the kids”, “pick up the phone”, “pick up a habit”.",
     examples:["Can you pick me up at eight?","Nobody picked up when I called."],
     colloc:"pick up the phone · pick someone up · pick up speed"},
    {term:"to put away", pos:"phrasal verb", def:"to return something to its usual place.",
     use:"Separable. Different from “put off” (postpone) and “put up with” (tolerate).",
     examples:["Please put your things away before you leave.","She put away the dishes."],
     colloc:"put the tools away · put it away · put away savings"},
    {term:"to look after", pos:"phrasal verb", def:"to take care of someone or something.",
     use:"Inseparable: the object always comes after “after”: “look after the baby”, “look after her” — never “look her after”.",
     examples:["Could you look after my dog this weekend?","Who looks after the accounts?"],
     colloc:"look after children · look after yourself · someone to look after it"},
    {term:"to fill out / fill in", pos:"phrasal verb", def:"to write the required information on a form.",
     use:"Separable, and both particles are correct (“out” is more American, “in” more British).",
     examples:["Fill out this form and hand it in at reception.","Have you filled it in yet?"],
     colloc:"fill out a form · fill in the blanks · fill it out"},
    {term:"favour", pos:"noun", def:"a helpful action you do for someone because they ask.",
     use:"“Do someone a favour”, “ask a favour”. The set opener “Can you do me a favour?” prepares your listener for a request.",
     examples:["Can you do me a favour and check this?","She asked me for a favour."],
     colloc:"do me a favour · a big favour · return the favour"},
    {term:"to mind", pos:"verb", def:"to be annoyed or bothered by something.",
     use:"“Would you mind + -ing” is a request; “I don’t mind” means it is fine with you. Answering “yes” to “Would you mind…?” is a refusal.",
     examples:["Would you mind closing the window?","I don’t mind waiting."],
     colloc:"would you mind · never mind · I don’t mind at all"},
    {term:"I’m afraid", pos:"expression", def:"a softener before bad news or a refusal.",
     use:"Never about fear here: “I’m afraid I can’t” is the standard polite “no”. It comes before the bad news.",
     examples:["I’m afraid I can’t help you today.","I’m afraid the shop is closed."],
     colloc:"I’m afraid not · I’m afraid so · I’m afraid I can’t"},
    {term:"to hand in", pos:"phrasal verb", def:"to give work or a document to a person in authority.",
     use:"Separable: “hand in your report”, “hand it in”. Compare “hand out” = distribute to many people.",
     examples:["Hand in your forms by Friday.","She handed it in late."],
     colloc:"hand in homework · hand in your notice · hand it in"},
    {term:"right away", pos:"adverbial phrase", def:"immediately.",
     use:"A natural way to accept a request: “I’ll do it right away.” Synonyms: at once, straight away.",
     examples:["I’ll send it right away.","He answered right away."],
     colloc:"right away · straight away · not right away"} ],
  grammar:[
    {name:"Two-part verbs and “will” for responding to requests", short:"Turn it off. — Sure, I’ll do it right now.",
     rule:"A two-part (phrasal) verb is a verb plus a particle whose meaning is often unpredictable from its parts. Separable verbs allow the object between the two parts and force it there when the object is a pronoun; inseparable verbs never split. When you agree to a request, English answers with “will”, because the decision is made at that moment.",
     form:["Separable, noun object: turn off the light / turn the light off.","Separable, pronoun object: turn it off (obligatory middle position).","Inseparable: look after the baby / look after her (never split).","Three-part: put up with the noise, run out of milk — never split.","Responses: Sure, I’ll do it. / Of course, I’ll take care of it. / I’m afraid I can’t right now."],
     notes:["The pronoun rule is the one to automate: “pick it up”, “turn them on”, “fill it out”. “Pick up it” is always wrong.","Three-part verbs behave like inseparable verbs because the second particle is really a preposition: “I can’t put up with it.”","Many two-part verbs have a one-word formal equivalent — put off / postpone, find out / discover, hand in / submit. Choose according to register.","Agreeing to a request uses “will”, not the present: “I’ll do it now”, not “I do it now”.","Softening a refusal is expected in English: give a reason after “I’m afraid I can’t” or you will sound abrupt."],
     deep:"Phrasal verbs are the reason fluent English sounds informal even when the topic is serious, and the reason careful learners can sound stiff. The grammar has exactly two moving parts. The first is separability, which you cannot deduce — you have to notice it — but the pronoun test settles it instantly: if “turn it off” sounds right, the verb separates; if only “look after it” works, it does not. The second is meaning, and here the particle is not decoration. “Up” often adds completion (drink up, fill up), “off” often adds disconnection (turn off, call off), “out” often adds distribution or discovery (hand out, find out). Learning them in families rather than alphabetically means you can guess new ones. On the response side, notice that English almost never answers a request with a bare “yes”: the pattern is agreement word plus “will” plus the action — “Sure, I’ll send it right away” — and that little formula will make you sound cooperative in a way “yes” alone never does.",
     chart:{title:"Word order with two-part verbs", cols:["Type","Noun object","Pronoun object","Example verbs"], rows:[["Separable","turn off the TV / turn the TV off","turn it off ✔ / turn off it ✘","turn on/off, pick up, put away, fill out, hand in"],["Inseparable","look after the kids","look after them ✔","look after, deal with, run into, get over"],["Three-part","put up with the noise","put up with it ✔","put up with, run out of, look forward to"]]},
     examples:["Could you turn the music down? — Sure, I’ll turn it down right now.","Don’t forget to hand in the form. — I’ve already handed it in.","Can you look after my laptop for ten minutes? — Of course.","I’m afraid I can’t pick you up today — my car’s at the garage."],
     watch:"With a pronoun, separable verbs must split: “pick it up”, “fill them out”, “turn it off”."},
    {name:"Requests with modals and “Would you mind…?”", short:"Can you help? Could you help? Would you mind helping?",
     rule:"English grades politeness in requests by distance. “Can you” is direct and friendly, “Could you” and “Would you” add distance and therefore courtesy, and “Would you mind + -ing” is the most indirect because it asks about the other person’s feelings rather than their actions.",
     form:["Can / Could / Will / Would you + base verb? → Could you open the window?","Would you mind + -ing? → Would you mind opening the window?","Would you mind if I + past? → Would you mind if I opened the window?","Accepting: Sure. / Of course. / No problem. / Not at all. / I’d be happy to.","Declining: I’m afraid I can’t… / Sorry, but… / I’d rather not, because…"],
     notes:["“Would you mind” is followed by -ing, never an infinitive: “Would you mind waiting?”, not “to wait”.","The answers are inverted: “No, not at all” means yes, I will do it; “Yes, I would mind” is a refusal. Because this confuses everyone, speakers usually reply with “Sure” or “Of course” plus the action.","“Would you mind if I…” asks permission for yourself and takes a past form (“if I borrowed your charger”); “Would you mind + -ing” asks the other person to act.","Longer requests are politer: adding “possibly”, “just” or a reason increases the courtesy (“Could you possibly send it today? I need it for the meeting.”).","“Can you” is not rude among friends and colleagues — over-formality with people you know well can sound cold or sarcastic."],
     deep:"Politeness in English is not a set of magic words but a strategy of leaving the other person an exit. Each step up the scale widens that exit. “Open the window” gives none. “Can you open the window?” asks about ability, which is easy to refuse in theory. “Could you” shifts into the hypothetical, so the request is one step removed from reality. “Would you mind opening the window?” does not even ask about the action — it asks whether the action would bother you, which is why the polarity of the answer flips: you are literally answering the question “is this a problem?”. Learners lose points in two opposite directions here. Some stay at the direct end and sound demanding; others use maximum politeness with close friends and sound distant. Match the level to the size of the favour and the closeness of the relationship, and always give a reason when you refuse — in English, a bare “no” is heard as a rebuke.",
     chart:{title:"Politeness scale for requests", cols:["Form","Level","When to use"], rows:[["Open the window.","direct order","emergencies, close family"],["Can you open the window?","informal","friends, colleagues, small favours"],["Could you open the window?","polite","most situations, safe default"],["Would you open the window?","polite / formal","service, written requests"],["Would you mind opening the window?","very polite","strangers, bigger favours"],["Would you mind if I opened the window?","permission","when you are the one acting"]]},
     examples:["Could you possibly send me the file before five?","Would you mind waiting a few minutes? — Not at all.","Would you mind if I used your charger? — Go ahead.","Can you give me a hand with this? — Sure, I’ll help you now."],
     watch:"“Would you mind + -ing”, and remember that “No, not at all” is an acceptance, not a refusal."} ],
  speaking:[
    {kind:"Favour chain", text:"Each student asks the next for a favour, moving one step up the politeness scale each time. The last student must refuse politely with a reason."},
    {kind:"Pronoun drill", text:"In pairs, give ten instructions using separable phrasal verbs. Your partner repeats each one replacing the object with a pronoun: “turn off the light” → “turn it off”."},
    {kind:"Role-play", text:"A neighbour asks you for three increasingly unreasonable favours. Accept the first two and decline the third without being rude."} ],
  tips:[
    "Pronoun in the middle for separable verbs — no exceptions.",
    "“Would you mind” + -ing, and “not at all” means yes.",
    "Agree with “Sure, I’ll…” rather than a bare “yes”."],
  quiz:{q:"Would you mind ___ the door?", options:["closing","to close","close"], answer:0, explain:"“Mind” is always followed by the gerund: Would you mind closing the door?"} },

{ n:7, title:"PAYLOAD", classes:"28–29", node:"node/07_payload", color:"#5b8def", theme:"What things are for, and telling people how to do them",
  overview:{
    intro:"A payload has a purpose. This node is about expressing purpose and function — what a tool is for, why you do something — using infinitives and gerunds, and then about giving clear instructions and suggestions with imperatives and infinitive structures.",
    goals:["Describe purpose with “to + verb”, “in order to” and “for + -ing”.","Choose correctly between an infinitive and a gerund after a verb, an adjective or a preposition.","Give instructions with imperatives and suggestions with infinitive patterns."],
    outcome:"By the end you can explain what any object or app is for, and give a set of clear instructions that a stranger could follow."
  },
  vocab:[
    {term:"purpose", pos:"noun", def:"the reason why something exists or is done.",
     use:"“The purpose of X is to + verb”. “On purpose” means deliberately, which is a different meaning.",
     examples:["The purpose of this form is to collect your data.","He did it on purpose."],
     colloc:"the main purpose · for this purpose · serve a purpose"},
    {term:"to be used for", pos:"expression", def:"to have a particular function.",
     use:"Two patterns: “It’s used for storing files” (+ -ing) or “It’s used to store files” (+ infinitive). Both are correct.",
     examples:["This app is used for editing photos.","A password manager is used to store keys safely."],
     colloc:"widely used for · what’s it used for · used to do something"},
    {term:"in order to", pos:"conjunction", def:"a more formal way of saying “to” when giving a reason.",
     use:"“In order to + verb” and the negative “in order not to + verb”, which is the standard way to express a negative purpose.",
     examples:["I left early in order to avoid the traffic.","She whispered in order not to wake the baby."],
     colloc:"in order to · in order not to · so as to"},
    {term:"device", pos:"noun", def:"a piece of equipment made for a particular job.",
     use:"Countable and slightly technical: “a mobile device”, “a safety device”. Everyday alternative: “gadget”.",
     examples:["This device measures air quality.","Turn off all electronic devices."],
     colloc:"a smart device · a safety device · mobile devices"},
    {term:"to avoid", pos:"verb", def:"to stay away from something, or stop it from happening.",
     use:"Always followed by a noun or -ing, never an infinitive: “avoid making mistakes”, not “avoid to make”.",
     examples:["Avoid clicking on strange links.","I left early to avoid the queue."],
     colloc:"avoid a problem · hard to avoid · avoid doing something"},
    {term:"instructions", pos:"noun (plural)", def:"the steps that tell you how to do something.",
     use:"Usually plural: “follow the instructions”. “An instruction” alone is rare and formal.",
     examples:["Read the instructions before you start.","He gave us clear instructions."],
     colloc:"follow instructions · clear instructions · instruction manual"},
    {term:"to make sure", pos:"expression", def:"to check that something is true or done.",
     use:"Followed by a clause: “Make sure you save it.” Also “make sure of + noun”. Extremely common in instructions.",
     examples:["Make sure the door is locked.","Make sure you back up your files first."],
     colloc:"make sure · just to make sure · make sure of it"},
    {term:"tool", pos:"noun", def:"an object or program used to do a job.",
     use:"Physical and digital: “a search tool”, “the right tool for the job”.",
     examples:["This is the best tool for the job.","We use an online tool to track hours."],
     colloc:"a useful tool · power tools · the right tool"},
    {term:"worth", pos:"adjective", def:"good enough to justify the time or money.",
     use:"“Worth + -ing”: “It’s worth trying.” Never an infinitive: not “worth to try”.",
     examples:["It’s worth checking the price online.","The trip was worth every peso."],
     colloc:"worth doing · well worth it · not worth the trouble"},
    {term:"to keep + -ing", pos:"pattern", def:"to continue doing something, or to do it repeatedly.",
     use:"Followed only by -ing: “keep trying”, “keep asking”. “Keep on + -ing” adds insistence.",
     examples:["Keep pressing the button until it beeps.","He keeps forgetting his password."],
     colloc:"keep going · keep trying · keep on asking"} ],
  grammar:[
    {name:"Infinitives and gerunds for uses and purposes", short:"It’s used to open files. / It’s used for opening files.",
     rule:"To express purpose, English offers an infinitive (“to + verb”) or a preposition plus a gerund (“for + -ing”). Which one you use depends on the frame: after most verbs and after “in order”, use the infinitive; after any preposition, use the gerund.",
     form:["Purpose with infinitive: I called to confirm the time. / in order to confirm / so as to confirm.","Negative purpose: in order not to / so as not to → I left early so as not to miss it.","Function with for + -ing: This key is for opening the back door.","Verb + gerund: enjoy, avoid, keep, finish, mind, suggest, recommend → I avoid using public Wi-Fi.","Verb + infinitive: want, need, decide, hope, plan, learn, try → We decided to change the password.","Preposition + gerund (always): interested in learning, good at fixing, instead of waiting, before leaving."],
     notes:["“For + verb” is impossible: never “for to open” or “I came for see you”. Use “to open”, “to see you”.","After every preposition the verb takes -ing. “To” is sometimes a preposition (look forward to seeing you) and sometimes an infinitive marker (want to see you) — this is why that pair confuses learners.","A few verbs take either form with almost no change: begin, start, continue, like, love, hate. A few change meaning: “I stopped smoking” (quit) vs “I stopped to smoke” (paused in order to).","“Remember / forget” follow the same logic: “remember to lock the door” (a task ahead) vs “remember locking the door” (a memory behind).","Both function patterns are correct and common: “used to store data” and “used for storing data”. Choose one and stay consistent inside a sentence."],
     deep:"Behind the lists there is one reliable principle: the infinitive looks forward, and the gerund names a thing. “To + verb” carries intention, direction and futurity, which is why it fits purpose (“I came to help”), plans (“I hope to travel”) and needs (“I need to sleep”). The gerund turns an action into a noun, which is why it fits after prepositions (a preposition always needs a noun-like object) and after verbs that talk about experiencing an action rather than aiming at it (enjoy, avoid, finish, mind). Test any doubtful case by substituting a noun: “I’m interested in coffee” works, so “interested in learning” must take -ing; “I want a coffee” works too, but “I want to learn” aims at something not yet real. Once you feel that difference, the small group of verbs that take both stops being a contradiction: they simply allow you to choose between naming an activity and aiming at a result.",
     chart:{title:"Infinitive or gerund?", cols:["Frame","Form","Example"], rows:[["Purpose (why)","to / in order to + verb","I wrote to explain the delay."],["Negative purpose","in order not to + verb","I wrote so as not to offend her."],["Function (what for)","for + -ing","This app is for tracking expenses."],["After a preposition","-ing","She’s good at solving problems."],["want, need, plan, decide, hope","to + verb","We plan to launch in May."],["avoid, enjoy, keep, finish, mind","-ing","Avoid clicking unknown links."]]},
     examples:["I use this app to keep track of my hours.","This little tool is for cleaning the keyboard.","She stayed late in order to finish the report.","I’m thinking about changing jobs, but I want to talk to my manager first."],
     watch:"Never write “for + infinitive”: purpose is “to do”, function is “for doing”."},
    {name:"Imperatives and infinitives for giving suggestions", short:"Check the cable. / Try restarting it. / It’s a good idea to back up.",
     rule:"The imperative is the base verb with no subject, used for instructions, directions and warnings. For suggestions, English softens the imperative with introductory phrases and infinitive structures so that advice does not sound like an order.",
     form:["Imperative: Open the app. / Don’t click that link. / Never share your password.","Softened imperative: Please check…, Just press…, Try pressing…, Make sure you save…","Infinitive suggestion: It’s a good idea to arrive early. / The best thing to do is to call them.","Verb + object + infinitive: I advise you to wait. / I’d recommend you to ask (or: I’d recommend asking).","Let’s + base verb for shared suggestions: Let’s try again tomorrow."],
     notes:["Imperatives have no subject, but you can add one for emphasis or contrast: “You sit here, and you take that side.”","Bare imperatives are normal in written instructions and recipes, and normal between friends, but they can sound abrupt in a request to a stranger — soften with “please”, “just”, or a modal.","“Try + -ing” suggests an experiment (“try restarting it”); “try + to” suggests effort against difficulty (“try to stay calm”).","“Recommend” and “suggest” are never followed by an object plus infinitive in careful English: say “I suggest waiting” or “I suggest that you wait”, not “I suggest you to wait”.","Negative imperatives always use “don’t”, even with “be”: “Don’t be late.”"],
     deep:"Instructions and suggestions are the same content at two different social temperatures. The imperative is maximally efficient — no subject, no modal, no hedge — which is exactly why manuals, recipes and emergency signs use it, and exactly why it can feel harsh in conversation. English therefore keeps a set of dampers. Adding “just” shrinks the effort (“just press enter”). Adding “try” frames the action as an experiment rather than a command, which also protects you if the advice fails. Moving to an infinitive structure removes you from the sentence entirely (“it’s a good idea to check first”), making the advice sound like a general truth rather than your personal instruction. When you write instructions for someone to follow, use imperatives and be consistent: mixing “open the file” with “you should open the file” makes a list harder to follow. When you advise a person about their own decision, move up the softness scale and let them own the choice.",
     chart:{title:"From instruction to suggestion", cols:["Form","Temperature","Example"], rows:[["Imperative","neutral / direct","Restart the router."],["just / please + imperative","softer","Just restart the router."],["Try + -ing","experimental","Try restarting the router."],["It’s a good idea to…","impersonal advice","It’s a good idea to restart it weekly."],["I’d recommend + -ing","personal advice","I’d recommend calling support."],["Let’s + verb","shared action","Let’s restart it together."]]},
     examples:["First, close all the windows. Then don’t touch anything for two minutes.","Try turning it off and on again before you call support.","It’s a good idea to write down the error message.","I’d recommend backing up your files before the update."],
     watch:"“I suggest you to call” is wrong. Say “I suggest calling” or “I suggest that you call”."} ],
  speaking:[
    {kind:"What’s it for?", text:"Bring three objects (or photos). Explain each one twice — once with “used to + verb”, once with “used for + -ing” — then invent a second, absurd purpose."},
    {kind:"Instruction relay", text:"Give your partner spoken instructions for a task they cannot see. Only imperatives allowed. Then repeat the same task as friendly suggestions."},
    {kind:"Troubleshooting", text:"One student describes a problem with a device or an app. The other gives four suggestions at four different softness levels."} ],
  tips:[
    "Purpose = “to do”; function = “for doing”. Never “for to do”.",
    "After every preposition, the verb ends in -ing.",
    "“Try + -ing” for experiments, “try to” for effort."],
  quiz:{q:"This program is used ___ passwords safely.", options:["for storing","for store","to storing"], answer:0, explain:"After the preposition “for”, the verb takes -ing. “Used to store” would also be correct with an infinitive."} },

{ n:8, title:"SYNC", classes:"32–33", node:"node/08_sync", color:"#2fbf9e", theme:"Anchoring events to a moment in time",
  overview:{
    intro:"Two clauses, one clock. This node teaches you to attach a description to a moment (“the year when I left home”) and to line up two events in time (“after I sent it, she called”). These structures are what turn a list of sentences into a narrative a listener can follow.",
    goals:["Define a time expression with a relative clause using when.","Link two events with when, after, before, while, as soon as and until.","Use the correct tense in each clause, especially in future time clauses."],
    outcome:"By the end you can narrate a turning point in your life with several linked clauses, and describe a routine where two things happen in a fixed order."
  },
  vocab:[
    {term:"moment", pos:"noun", def:"a very short period of time; a point in time.",
     use:"“The moment (that)” works as a conjunction meaning “as soon as”: “Call me the moment you arrive.”",
     examples:["I remember the moment when I got the news.","Wait a moment, please."],
     colloc:"at the moment · in a moment · the moment you arrive"},
    {term:"turning point", pos:"noun", def:"the moment when an important change happens.",
     use:"Very useful with relative clauses of time: “That was the turning point when everything changed.”",
     examples:["Losing that job was a turning point in my life.","The meeting was a turning point for the company."],
     colloc:"a major turning point · reach a turning point"},
    {term:"as soon as", pos:"conjunction", def:"immediately after.",
     use:"Followed by a present tense for the future: “I’ll call you as soon as I get home”, never “as soon as I will get”.",
     examples:["As soon as the file uploads, we can start.","Let me know as soon as you hear anything."],
     colloc:"as soon as possible · as soon as I can"},
    {term:"while", pos:"conjunction", def:"during the same period as.",
     use:"For two simultaneous actions, often with a continuous tense: “While I was cooking, she called.”",
     examples:["While you were out, someone left a message.","I listen to podcasts while I drive."],
     colloc:"while waiting · meanwhile · a while ago"},
    {term:"until", pos:"conjunction / preposition", def:"up to the moment when something happens.",
     use:"Marks an end point, not a duration: “I waited until six”. With a negative it means “not before”: “Don’t leave until I call.”",
     examples:["We stayed until the rain stopped.","I won’t decide until I speak to her."],
     colloc:"until now · up until then · not until"},
    {term:"period", pos:"noun", def:"a length of time with a beginning and an end.",
     use:"Often followed by “of”: “a period of six months”, “a difficult period in my life”.",
     examples:["That was a strange period of my life.","Over a period of two years, everything changed."],
     colloc:"a short period · during that period · a period of change"},
    {term:"to graduate", pos:"verb", def:"to finish a course of study and receive a qualification.",
     use:"“Graduate from + institution”, “graduate in + subject”: “She graduated from university in 2020.”",
     examples:["When I graduated, I had no idea what to do.","He graduated in engineering."],
     colloc:"graduate from · a recent graduate · graduation day"},
    {term:"to realise", pos:"verb", def:"to understand something suddenly and clearly.",
     use:"Followed by a that-clause: “I realised that I was wrong.” Not the same as “to make something real”, which is a rarer use.",
     examples:["I only realised the problem when it was too late.","She realised she had forgotten her keys."],
     colloc:"suddenly realise · didn’t realise · come to realise"},
    {term:"meanwhile", pos:"adverb", def:"at the same time as something else, in a different place.",
     use:"An adverb, not a conjunction: it connects sentences, not clauses. “Meanwhile, the guests were waiting.”",
     examples:["Meanwhile, nobody had told the client.","I’ll finish this; meanwhile, you can start the other file."],
     colloc:"meanwhile · in the meantime"},
    {term:"eventually", pos:"adverb", def:"in the end, after a long time or several problems.",
     use:"False friend for Spanish speakers: it does not mean “possibly”. That is “possibly” or “maybe”.",
     examples:["Eventually they answered my email.","She eventually agreed to help."],
     colloc:"eventually happen · eventually gave up"} ],
  grammar:[
    {name:"Relative clauses of time with “when”", short:"the day when we met · the year when everything changed",
     rule:"A relative clause of time defines or describes a time expression. “When” introduces it, and it always refers back to a noun that names a period or a point in time: day, year, moment, summer, time.",
     form:["noun of time + when + subject + verb → I still remember the day when we met.","“When” can often be dropped: the day we met, the year I graduated.","Alternatives: the day (that) we met, the day on which we met (formal).","Non-defining, with a comma: In 2020, when everything closed, I started studying online."],
     notes:["“When” only follows a time noun. For places use “where”, for reasons “why”, for people “who”, for things “that / which”.","In defining clauses “when” is optional and its absence is very common in speech: “Do you remember the night we got lost?”","A comma changes the job of the clause: with no comma it identifies which time you mean; with commas it adds extra information about a time already identified.","Do not repeat the time word inside the clause: “the day when we met on that day” is redundant.","“When” as a relative pronoun is different from “when” as a conjunction of time — the first modifies a noun, the second modifies the whole clause."],
     deep:"Relative clauses of time solve a specific problem: how to say which moment you mean without starting a new sentence. Compare “I remember a day. We met that day.” with “I remember the day when we met.” The information is identical, but the second version subordinates one idea to the other, and subordination is what makes writing sound adult. The definite article is a good clue that you need one: as soon as you say “the day”, “the year” or “the moment”, your listener expects you to specify which — and a “when” clause is the natural specification. The optional “when” is worth practising deliberately, because dropping it is a fast route to a more natural rhythm: “the summer I turned eighteen” sounds like a story; “the summer when I turned eighteen” sounds like a report. Both are correct, so use the choice for style.",
     chart:{title:"Relative words by type of noun", cols:["Noun refers to","Relative word","Example"], rows:[["a time","when (or nothing)","the year when I left / the year I left"],["a place","where","the city where I grew up"],["a reason","why","the reason why she resigned"],["a person","who / that","the teacher who helped me"],["a thing","that / which","the app that tracks my hours"]]},
     examples:["That was the summer when I decided to change careers.","Do you remember the moment we realised the file was gone?","In 2019, when I was still studying, I worked two jobs.","There are days when nothing goes right."],
     watch:"Use “when” only after a time noun; after a place noun use “where”, not “when”."},
    {name:"Adverbial clauses of time: when, after, before", short:"After I finish, I’ll call you. / I’ll call when I get home.",
     rule:"An adverbial clause of time says when the main action happens. It can come first or second in the sentence; if it comes first, it takes a comma. English never uses “will” inside a time clause — the future is carried by the main clause alone.",
     form:["When + subject + verb: When I got home, everyone was asleep.","After / Before + clause: After she left, I locked up. / Before you go, sign this.","Future rule: As soon as I finish, I’ll send it. (present tense in the time clause)","Reduced forms with -ing: After finishing, I went home. / Before leaving, check the lights.","Order is free: I’ll call you when I arrive. / When I arrive, I’ll call you."],
     notes:["This is the rule that decides marks in exams: “When I will arrive” is always wrong. Use the present simple, or the present perfect if you want to stress completion: “as soon as I’ve finished”.","“When” allows the two events to be either simultaneous or sequential; “while” insists they overlap; “as soon as” insists there is no gap between them.","In past narration, “after” and “before” already show the order, so the past perfect is optional: “After I sent it, she called” is as correct as “After I had sent it…”.","A reduced clause with -ing is only possible when both clauses share the same subject: “Before leaving, I locked the door” (I left, I locked).","Punctuation: comma when the time clause opens the sentence, no comma when it closes it."],
     deep:"Time clauses look easy and then quietly break sentences, because they run on a rule that feels illogical: the clause is about the future, but its verb is in the present. The reason is that English marks the future only once. The main clause carries “will” or “going to”, and once the sentence is anchored in the future, the subordinate clause does not need to repeat it — the conjunction (“when”, “after”, “as soon as”) already tells you where you are. Spanish uses a subjunctive in exactly this slot, which is why the error is so persistent for Spanish speakers: there is a form in your first language, and English seems to leave the slot empty. It does not — it fills it with the present simple. The second thing to master is conjunction choice, because it encodes your interpretation of events: “when the manager arrived, we started” (sequence), “while the manager was arriving, we started” (overlap), “as soon as the manager arrived, we started” (immediate). Same facts, three different stories.",
     chart:{title:"Tense in time clauses", cols:["Time reference","Time clause","Main clause"], rows:[["Future","present simple: when I get home","will / going to: I’ll call you"],["Future, stressing completion","present perfect: as soon as I’ve finished","will: I’ll send it"],["Present habit","present simple: when I get home","present simple: I make coffee"],["Past sequence","simple past: after I sent it","simple past: she called"],["Past, earlier event stressed","past perfect: after I had sent it","simple past: she called"]]},
     examples:["I’ll let you know as soon as I hear from them.","Before you send the email, check the attachment.","When I was living in Cali, I used to cycle to work every day.","After the update finished, everything worked normally again."],
     watch:"Never put “will” in the time clause: “when I arrive”, not “when I will arrive”."} ],
  speaking:[
    {kind:"Turning point", text:"Tell the story of one turning point in your life. Include at least two relative clauses of time and three adverbial time clauses."},
    {kind:"Chain narration", text:"Build a group story. Each student adds one sentence that must start with after, before, when, while or as soon as."},
    {kind:"Plan the day", text:"Describe tomorrow to your partner in six sentences, each containing a future time clause. Your partner corrects any “will” in the wrong clause."} ],
  tips:[
    "Time clause = present tense, even for the future.",
    "Drop “when” in defining clauses for a more natural rhythm: “the day we met”.",
    "Comma only when the time clause comes first."],
  quiz:{q:"I’ll send you the file as soon as I ___ it.", options:["finish","will finish","am going to finish"], answer:0, explain:"Time clauses take the present simple even when the meaning is future; “will” belongs only in the main clause."} }
];
